import {
    Table,
    BasicImageColumn,
    GenericColumn,
    IntegerColumn,
    ReferenceColumn,
    StringColumn,
    TranslatedTextColumn,
    BooleanColumn,
    UserRolesColumn,
} from '../../db'

export const sc_category = Table({
    allowWebServiceAccess: true,
    attributes: {
        kagami_csindex_enabled: true,
        synch_attachments: true,
        text_index_translations: true,
        update_synch: true,
    },
    display: 'title',
    extends: 'sys_metadata',
    extensible: true,
    label: 'Category',
    name: 'sc_category',
    schema: {
        image: BasicImageColumn({
            attributes: {
                pdf_cell_type: 'basic_image',
            },
            label: 'Image',
        }),
        icon: GenericColumn({
            attributes: {
                pdf_cell_type: 'image',
            },
            columnType: 'user_image',
            label: [
                {
                    hint: 'Icon to use to signify this category',
                    label: 'Icon',
                    plural: 'Icons',
                    language: 'en',
                },
            ],
        }),
        header_icon: GenericColumn({
            attributes: {
                pdf_cell_type: 'image',
            },
            columnType: 'user_image',
            label: [
                {
                    hint: 'Icon to use on category headers',
                    label: 'Header icon',
                    plural: 'Header icons',
                    language: 'en',
                },
            ],
        }),
        homepage_image: GenericColumn({
            attributes: {
                pdf_cell_type: 'image',
            },
            columnType: 'user_image',
            label: 'Homepage image',
        }),
        mobile_picture: GenericColumn({
            attributes: {
                pdf_cell_type: 'image',
            },
            columnType: 'user_image',
            label: [
                {
                    hint: 'The picture to use when displayed as a card in the classic mobile UI',
                    label: 'Classic Mobile image',
                    plural: 'Classic Mobile images',
                    language: 'en',
                },
            ],
        }),
        order: IntegerColumn({
            default: '0',
            label: [
                {
                    hint: 'Order this category will use when displayed on lists',
                    label: 'Order',
                    plural: 'Orders',
                    language: 'en',
                },
            ],
        }),
        location: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                tree_picker: true,
            },
            label: 'Location',
            referenceTable: 'cmn_location',
        }),
        parent: ReferenceColumn({
            attributes: {
                ref_auto_completer: 'AJAXTableCompleter',
                ref_ac_columns: 'sc_catalog',
            },
            label: 'Parent',
            referenceTable: 'sc_category',
            referenceQual: 'javascript: new Category().getReferenceQual(current);',
        }),
        sc_catalog: ReferenceColumn({
            default: 'javascript: new Category().getDefaultCatalogValue();',
            label: 'Catalog',
            referenceTable: 'sc_catalog',
            referenceQual: "javascript: new SNCCatalogUtil().getReferenceQual('');",
        }),
        homepage_renderer: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            default: '47ebe8aa3742300054b6a3549dbe5dfa',
            label: [
                {
                    hint: 'The homepage renderer for this category',
                    label: 'Homepage renderer',
                    plural: 'Homepage renderers',
                    language: 'en',
                },
            ],
            mandatory: false,
            referenceTable: 'sc_homepage_renderer',
        }),
        module: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Override normal category behavior and make this category a link to a URI specified by the referenced module',
                    label: 'Module link',
                    plural: 'Module links',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_app_module',
        }),
        entitlement_script: GenericColumn({
            columnType: 'script_plain',
            label: 'Entitlement script',
            maxLength: 4000,
        }),
        mobile_subcategory_render_type: StringColumn({
            default: 'list',
            choices: {
                card: {
                    label: 'Card',
                    sequence: 1,
                },
                list: {
                    label: 'List',
                    sequence: 0,
                },
            },
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Choose the way in which subcategories will be rendered in listings for the classic mobile UI',
                    label: 'Classic Mobile Subcategory Render Type',
                    plural: 'Classic Mobile Subcategory Render Types',
                    language: 'en',
                },
            ],
        }),
        sys_id: GenericColumn({
            columnType: 'GUID',
            label: 'Sys ID',
            maxLength: 32,
            primary: true,
        }),
        title: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Title',
            mandatory: true,
            maxLength: 100,
            textIndex: true,
        }),
        description: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Description',
            maxLength: 4000,
            textIndex: true,
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        mobile_hide_description: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Hide the description of the category being browsed in the classic mobile UI',
                    label: 'Hide description (classic mobile browsing)',
                    plural: 'Hide description (classic mobile browsing)',
                    language: 'en',
                },
            ],
        }),
        roles: UserRolesColumn({
            array: true,
            attributes: {
                record_watcher_blacklist: true,
            },
            label: [
                {
                    hint: 'Who can view this catalog category',
                    label: 'Roles',
                    plural: 'Roles',
                    language: 'en',
                },
            ],
        }),
    },
    textIndex: true,
})
